1	import { Plugin, PluginContext } from './plugin';
2	import { BuildOptions, BuildResult, Page } from './types';
3	
4	type StageHook = 'onStart' | 'beforeBuild' | 'afterBuild' | 'onEnd';
5	
6	function isThenable(value: unknown): value is Promise<unknown> {
7	  return !!value && typeof (value as { then?: unknown }).then === 'function';
8	}
9	
10	/**
11	 * Orchestrates a build across a list of Plugins. For each stage, every
12	 * plugin's hook for that stage runs in list order before the next stage
13	 * begins; `onFile` runs the full plugin chain once per page (in list
14	 * order) so a plugin can transform a page before a later plugin persists
15	 * it.
16	 *
17	 * `runSync` powers `buildSite()` and requires every hook to complete
18	 * synchronously (it throws if a plugin returns a Promise); use `run` for
19	 * pipelines that include async plugins (e.g. DevServerPlugin).
20	 */
21	export class SSGEngine {
22	  constructor(private readonly plugins: Plugin[]) {}
23	
24	  runSync(options: BuildOptions): BuildResult {
25	    const ctx: PluginContext = { options, pages: [] };
26	
27	    this.runStageSync('onStart', ctx);
28	    this.runStageSync('beforeBuild', ctx);
29	    ctx.pages = ctx.pages.map((page) => this.runFileHooksSync(page, ctx));
30	    this.runStageSync('afterBuild', ctx);
31	    this.runStageSync('onEnd', ctx);
32	
33	    return { pages: ctx.pages, outputDir: options.outputDir };
34	  }
35	
36	  async run(options: BuildOptions): Promise<BuildResult> {
37	    const ctx: PluginContext = { options, pages: [] };
38	
39	    await this.runStage('onStart', ctx);
40	    await this.runStage('beforeBuild', ctx);
41	
42	    const pages: Page[] = [];
43	    for (const page of ctx.pages) {
44	      pages.push(await this.runFileHooks(page, ctx));
45	    }
46	    ctx.pages = pages;
47	
48	    await this.runStage('afterBuild', ctx);
49	    await this.runStage('onEnd', ctx);
50	
51	    return { pages: ctx.pages, outputDir: options.outputDir };
52	  }
53	
54	  private runStageSync(hook: StageHook, ctx: PluginContext): void {
55	    for (const plugin of this.plugins) {
56	      const result = plugin[hook]?.(ctx);
57	      if (isThenable(result)) {
58	        throw new Error(
59	          `Plugin "${plugin.name}" returned a Promise from ${hook}(); use SSGEngine.run() for async plugin pipelines.`
60	        );
61	      }
62	    }
63	  }
64	
65	  private runFileHooksSync(page: Page, ctx: PluginContext): Page {
66	    let current = page;
67	    for (const plugin of this.plugins) {
68	      const result = plugin.onFile?.(current, ctx);
69	      if (isThenable(result)) {
70	        throw new Error(
71	          `Plugin "${plugin.name}" returned a Promise from onFile(); use SSGEngine.run() for async plugin pipelines.`
72	        );
73	      }
74	      if (result) current = result;
75	    }
76	    return current;
77	  }
78	
79	  private async runStage(hook: StageHook, ctx: PluginContext): Promise<void> {
80	    for (const plugin of this.plugins) {
81	      await plugin[hook]?.(ctx);
82	    }
83	  }
84	
85	  private async runFileHooks(page: Page, ctx: PluginContext): Promise<Page> {
86	    let current = page;
87	    for (const plugin of this.plugins) {
88	      const result = await plugin.onFile?.(current, ctx);
89	      if (result) current = result;
90	    }
91	    return current;
92	  }
93	}
