1	import { SSGEngine } from './engine';
2	import { createMarkdownPlugin } from './plugins/markdownPlugin';
3	import { createTemplatePlugin } from './plugins/templatePlugin';
4	import { BuildOptions, BuildResult } from './types';
5	
6	export { findMarkdownFiles, loadPages } from './markdownLoader';
7	
8	/**
9	 * Builds the site using the built-in Markdown + Template plugins, run
10	 * synchronously through SSGEngine. For a custom plugin pipeline (including
11	 * async plugins like DevServerPlugin), construct an `SSGEngine` directly
12	 * and call `run()`.
13	 */
14	export function buildSite(options: BuildOptions): BuildResult {
15	  const engine = new SSGEngine([createMarkdownPlugin(), createTemplatePlugin()]);
16	  return engine.runSync(options);
