1	#!/usr/bin/env node
2	import { Command } from 'commander';
3	import * as path from 'path';
4	import { loadConfig } from './config';
5	import { startDevServer } from './devServer';
6	import { SSGEngine } from './engine';
7	import { buildSite } from './generator';
8	import { createMarkdownPlugin } from './plugins/markdownPlugin';
9	import { createTemplatePlugin } from './plugins/templatePlugin';
10	
11	export function run(argv: string[]): void {
12	  const program = new Command();
13	
14	  program.name('ssg').description('A static site generator').version('1.0.0');
15	
16	  program
17	    .command('build')
18	    .description('Generate the site from Markdown content')
19	    .option('--content <dir>', 'content directory', './content')
20	    .option('--output <dir>', 'output directory', './dist')
21	    .option('--templates <dir>', 'templates directory', './templates')
22	    .option('--config <path>', 'plugin config file (e.g. ssg.config.ts); enables the custom plugin pipeline')
23	    .action((opts: { content: string; output: string; templates: string; config?: string }) => {
24	      const contentDir = path.resolve(process.cwd(), opts.content);
25	      const outputDir = path.resolve(process.cwd(), opts.output);
26	      const templatesDir = path.resolve(process.cwd(), opts.templates);
27	
28	      if (opts.config) {
29	        const configPath = path.resolve(process.cwd(), opts.config);
30	        const config = loadConfig(configPath);
31	        const plugins = config.plugins.length > 0 ? config.plugins : [createMarkdownPlugin(), createTemplatePlugin()];
32	        const engine = new SSGEngine(plugins);
33	        engine
34	          .run({
35	            contentDir: config.contentDir ? path.resolve(process.cwd(), config.contentDir) : contentDir,
36	            outputDir: config.outputDir ? path.resolve(process.cwd(), config.outputDir) : outputDir,
37	            templatesDir: config.templatesDir ? path.resolve(process.cwd(), config.templatesDir) : templatesDir,
38	          })
39	          .then((result) => {
40	            // eslint-disable-next-line no-console
41	            console.log(`Built ${result.pages.length} page(s) into ${result.outputDir}`);
42	          })
43	          .catch((err) => {
44	            // eslint-disable-next-line no-console
45	            console.error('Build failed:', err instanceof Error ? err.message : err);
46	            process.exitCode = 1;
47	          });
48	        return;
49	      }
50	
51	      const result = buildSite({ contentDir, outputDir, templatesDir });
52	      // eslint-disable-next-line no-console
53	      console.log(`Built ${result.pages.length} page(s) into ${result.outputDir}`);
54	    });
55	
56	  program
57	    .command('serve')
58	    .description('Build the site and serve it with live reload')
59	    .option('--content <dir>', 'content directory', './content')
60	    .option('--output <dir>', 'output directory', './dist')
61	    .option('--templates <dir>', 'templates directory', './templates')
62	    .option('--port <port>', 'port to serve on', '3000')
63	    .action(async (opts: { content: string; output: string; templates: string; port: string }) => {
64	      const contentDir = path.resolve(process.cwd(), opts.content);
65	      const outputDir = path.resolve(process.cwd(), opts.output);
66	      const templatesDir = path.resolve(process.cwd(), opts.templates);
67	      const port = parseInt(opts.port, 10);
68	      const server = await startDevServer({ contentDir, outputDir, templatesDir, port });
69	      // eslint-disable-next-line no-console
70	      console.log(`Serving ${outputDir} at http://localhost:${server.port} (watching ${opts.content}, ${opts.templates})`);
71	    });
72	
73	  program.parse(argv);
74	}
75	
76	if (require.main === module) {
77	  run(process.argv);
78	}
