1	import * as fs from 'fs';
2	import * as path from 'path';
3	import { parseMarkdown } from './parser';
4	import { Page } from './types';
5	
6	const MARKDOWN_EXTENSIONS = new Set(['.md', '.markdown']);
7	
8	/**
9	 * Recursively finds markdown files under `dir`, returning paths relative to
10	 * `dir` (using forward slashes).
11	 */
12	export function findMarkdownFiles(dir: string): string[] {
13	  const results: string[] = [];
14	
15	  function walk(current: string) {
16	    const entries = fs.readdirSync(current, { withFileTypes: true });
17	    for (const entry of entries) {
18	      const fullPath = path.join(current, entry.name);
19	      if (entry.isDirectory()) {
20	        walk(fullPath);
21	      } else if (MARKDOWN_EXTENSIONS.has(path.extname(entry.name).toLowerCase())) {
22	        results.push(path.relative(dir, fullPath).split(path.sep).join('/'));
23	      }
24	    }
25	  }
26	
27	  if (fs.existsSync(dir)) {
28	    walk(dir);
29	  }
30	
31	  return results;
32	}
33	
34	export function loadPages(contentDir: string): Page[] {
35	  const files = findMarkdownFiles(contentDir);
36	  return files.map((relativePath) => {
37	    const raw = fs.readFileSync(path.join(contentDir, relativePath), 'utf-8');
38	    return parseMarkdown(raw, relativePath);
39	  });
40	}
