1	import matter from 'gray-matter';
2	import { marked } from 'marked';
3	import * as path from 'path';
4	import { FrontMatter, Page } from './types';
5	
6	marked.setOptions({ gfm: true });
7	
8	/**
9	 * Turns a source-relative markdown path into a title-cased fallback title,
10	 * used when a page has no frontmatter title.
11	 */
12	function titleFromSlug(slug: string): string {
13	  const base = slug.split('/').pop() || slug;
14	  return base
15	    .replace(/[-_]+/g, ' ')
16	    .replace(/\b\w/g, (c) => c.toUpperCase());
17	}
18	
19	function normalizeTags(rawTags: unknown): string[] {
20	  if (Array.isArray(rawTags)) {
21	    return rawTags.map((t) => String(t));
22	  }
23	  if (typeof rawTags === 'string' && rawTags.trim().length > 0) {
24	    return rawTags.split(',').map((t) => t.trim());
25	  }
26	  return [];
27	}
28	
29	function normalizeDate(rawDate: unknown): string | undefined {
30	  if (rawDate === undefined || rawDate === null) return undefined;
31	  if (rawDate instanceof Date) return rawDate.toISOString().slice(0, 10);
32	  return String(rawDate);
33	}
34	
35	/**
36	 * Parses a single markdown file's raw text (with optional frontmatter) into
37	 * a Page. `relativePath` is the file's path relative to the content
38	 * directory, using forward slashes, e.g. "posts/hello-world.md".
39	 */
40	export function parseMarkdown(raw: string, relativePath: string): Page {
41	  const { data, content } = matter(raw);
42	  const frontMatter = data as FrontMatter;
43	
44	  const parsedPath = path.posix.parse(relativePath.split(path.sep).join('/'));
45	  const slug = parsedPath.dir ? `${parsedPath.dir}/${parsedPath.name}` : parsedPath.name;
46	
47	  const html = marked.parse(content, { async: false }) as string;
48	
49	  return {
50	    sourcePath: relativePath,
51	    slug,
52	    outputFile: `${slug}.html`,
53	    title: frontMatter.title ? String(frontMatter.title) : titleFromSlug(slug),
54	    date: normalizeDate(frontMatter.date),
55	    tags: normalizeTags(frontMatter.tags),
56	    html,
57	    template: frontMatter.template ? String(frontMatter.template) : undefined,
58	  };
59	}
