3	/**
4	 * Shared state threaded through a build's plugin pipeline. `pages` starts
5	 * empty and is populated during `beforeBuild` (typically by a
6	 * content-loading plugin such as MarkdownPlugin) before any `onFile` hook
7	 * runs.
8	 */
9	export interface PluginContext {
10	  readonly options: BuildOptions;
11	  pages: Page[];
12	}
13	
14	/**
15	 * A build-lifecycle extension. Every hook is optional; a plugin implements
16	 * only the stages it cares about. Hooks run in plugin-list order within
17	 * each stage (see SSGEngine), so a plugin that transforms page content in
18	 * `onFile` must be listed before a plugin that persists it (e.g.
19	 * TemplatePlugin) for the transform to take effect.
20	 */
21	export interface Plugin {
22	  name: string;
23	  onStart?(ctx: PluginContext): void | Promise<void>;
24	  beforeBuild?(ctx: PluginContext): void | Promise<void>;
25	  onFile?(page: Page, ctx: PluginContext): Page | void | Promise<Page | void>;
26	  afterBuild?(ctx: PluginContext): void | Promise<void>;
27	  onEnd?(ctx: PluginContext): void | Promise<void>;
28	}
