1	import * as fs from 'fs';
2	import { loadPages } from '../markdownLoader';
3	import { Plugin, PluginContext } from '../plugin';
4	
5	/**
6	 * Built-in plugin that loads and parses the site's Markdown content.
7	 * Populates `ctx.pages` during `beforeBuild`, before any `onFile` hook
8	 * runs.
9	 */
10	export function createMarkdownPlugin(): Plugin {
11	  return {
12	    name: 'markdown',
13	    beforeBuild(ctx: PluginContext) {
14	      const { contentDir } = ctx.options;
15	      if (!fs.existsSync(contentDir)) {
16	        throw new Error(`Content directory not found: ${contentDir}`);
17	      }
18	      ctx.pages.push(...loadPages(contentDir));
19	    },
20	  };
21	}
