8	const DEFAULT_STYLESHEET = `body { font-family: sans-serif; max-width: 40rem; margin: 2rem auto; padding: 0 1rem; line-height: 1.6; }
9	header { margin-bottom: 2rem; }
10	.page-list { list-style: none; padding: 0; }
11	.page-list li { margin-bottom: 0.5rem; }
12	.tags { list-style: none; padding: 0; display: flex; gap: 0.5rem; }
13	.tags li { background: #eee; border-radius: 0.25rem; padding: 0.1rem 0.5rem; font-size: 0.85rem; }
14	`;
15	
16	function writeFile(filePath: string, contents: string): void {
17	  fs.mkdirSync(path.dirname(filePath), { recursive: true });
18	  fs.writeFileSync(filePath, contents, 'utf-8');
19	}
20	
21	/**
22	 * Built-in plugin that renders each page to HTML (via a Handlebars
23	 * TemplateEngine when `templatesDir` is set, falling back to the built-in
24	 * renderer otherwise) and writes it, plus the site index and default
25	 * stylesheet, to `outputDir`.
26	 */
27	export function createTemplatePlugin(): Plugin {
28	  let engine: TemplateEngine | undefined;
29	
30	  return {
31	    name: 'template',
32	    beforeBuild(ctx: PluginContext) {
33	      const { outputDir, templatesDir } = ctx.options;
34	      fs.mkdirSync(outputDir, { recursive: true });
35	      engine = templatesDir && fs.existsSync(templatesDir) ? new TemplateEngine(templatesDir) : undefined;
36	    },
37	    onFile(page: Page, ctx: PluginContext) {
38	      const html = engine?.renderPage(page, ctx.pages) ?? renderPage(page);
39	      writeFile(path.join(ctx.options.outputDir, page.outputFile), html);
40	    },
41	    afterBuild(ctx: PluginContext) {
42	      const indexHtml = engine?.renderIndex(ctx.pages) ?? renderIndex(ctx.pages);
43	      writeFile(path.join(ctx.options.outputDir, 'index.html'), indexHtml);
44	      writeFile(path.join(ctx.options.outputDir, 'style.css'), DEFAULT_STYLESHEET);
45	    },
46	  };
47	}
