1	import * as fs from 'fs';
2	import * as ts from 'typescript';
3	import { Plugin } from './plugin';
4	
5	export interface SSGConfig {
6	  plugins: Plugin[];
7	  contentDir?: string;
8	  outputDir?: string;
9	  templatesDir?: string;
10	}
11	
12	let tsRequireHookRegistered = false;
13	
14	/**
15	 * Registers a `require.extensions['.ts']` handler that transpiles
16	 * TypeScript to CommonJS on the fly via the TypeScript compiler API, so
17	 * plain `require()` can load `ssg.config.ts` (and any `.ts` plugin modules
18	 * it imports) without a build step. Under Jest, ts-jest already transforms
19	 * `.ts` requires before Node's `require.extensions` is consulted, so this
20	 * hook is inert there.
21	 */
22	function registerTsRequireHook(): void {
23	  if (tsRequireHookRegistered || require.extensions['.ts']) {
24	    tsRequireHookRegistered = true;
25	    return;
26	  }
27	  tsRequireHookRegistered = true;
28	
29	  require.extensions['.ts'] = (mod: NodeJS.Module, filename: string) => {
30	    const source = fs.readFileSync(filename, 'utf-8');
31	    const { outputText } = ts.transpileModule(source, {
32	      compilerOptions: {
33	        module: ts.ModuleKind.CommonJS,
34	        target: ts.ScriptTarget.ES2020,
35	        esModuleInterop: true,
36	      },
37	      fileName: filename,
38	    });
39	    (mod as unknown as { _compile(code: string, filename: string): void })._compile(outputText, filename);
40	  };
41	}
42	
43	/**
44	 * Loads plugin configuration from `configPath` (an `ssg.config.ts` or
45	 * `.js` module exporting an `SSGConfig`, either as `export default` or
46	 * CommonJS `module.exports`). Returns `{ plugins: [] }` when the file
47	 * doesn't exist, so callers can fall back to a default plugin set.
48	 */
49	export function loadConfig(configPath: string): SSGConfig {
50	  if (!fs.existsSync(configPath)) {
51	    return { plugins: [] };
52	  }
53	
54	  registerTsRequireHook();
55	  delete require.cache[require.resolve(configPath)];
56	  const loaded = require(configPath);
57	  const config = (loaded?.default ?? loaded) as Partial<SSGConfig>;
58	
59	  return {
60	    plugins: Array.isArray(config.plugins) ? config.plugins : [],
61	    contentDir: config.contentDir,
62	    outputDir: config.outputDir,
63	    templatesDir: config.templatesDir,
64	  };
65	}
