38	function liveReloadScript(): string {
39	  return `<script>(function(){var socket=new WebSocket((location.protocol==='https:'?'wss://':'ws://')+location.host+'${LIVE_RELOAD_PATH}');socket.addEventListener('message',function(event){if(event.data==='reload'){location.reload();}});})();</script>`;
40	}
41	
42	/**
43	 * Injects the live-reload client script into an HTML document, just before
44	 * `</body>` when present, otherwise appended to the end of the document.
45	 */
46	export function injectLiveReload(html: string): string {
47	  const script = liveReloadScript();
48	  if (html.includes('</body>')) {
49	    return html.replace('</body>', `${script}</body>`);
50	  }
51	  return `${html}${script}`;
52	}
