54	function serveStaticFile(req: http.IncomingMessage, res: http.ServerResponse, outputDir: string): void {
55	  const requestUrl = new URL(req.url || '/', 'http://localhost');
56	  let pathname = decodeURIComponent(requestUrl.pathname);
57	  if (pathname.endsWith('/')) {
58	    pathname += 'index.html';
59	  }
60	
61	  const resolvedRoot = path.resolve(outputDir);
62	  const filePath = path.resolve(resolvedRoot, `.${pathname}`);
63	
64	  if (filePath !== resolvedRoot && !filePath.startsWith(resolvedRoot + path.sep)) {
65	    res.writeHead(403, { 'Content-Type': 'text/plain' });
66	    res.end('Forbidden');
67	    return;
68	  }
69	
70	  fs.readFile(filePath, (err, data) => {
71	    if (err) {
72	      res.writeHead(404, { 'Content-Type': 'text/plain' });
73	      res.end('Not found');
74	      return;
75	    }
76	
77	    const ext = path.extname(filePath).toLowerCase();
78	    const contentType = MIME_TYPES[ext] || 'application/octet-stream';
79	    res.writeHead(200, { 'Content-Type': contentType });
80	    res.end(ext === '.html' ? injectLiveReload(data.toString('utf-8')) : data);
81	  });
82	}
83	
84	/**
85	 * Starts a live-reload development server: serves the built site from
86	 * `outputDir`, watches `contentDir`/`templatesDir` with chokidar, rebuilds
87	 * on change, and pushes a reload message to connected browsers over a
88	 * WebSocket at `/__livereload`.
89	 */
90	export async function startDevServer(options: DevServerOptions): Promise<DevServer> {
91	  const { contentDir, outputDir, templatesDir, port = 3000 } = options;
92	
93	  buildSite({ contentDir, outputDir, templatesDir });
94	
95	  const server = http.createServer((req, res) => serveStaticFile(req, res, outputDir));
96	  const wss = new WebSocketServer({ server, path: LIVE_RELOAD_PATH });
97	
98	  function broadcastReload(): void {
99	    for (const client of wss.clients) {
100	      if (client.readyState === client.OPEN) {
101	        client.send('reload');
102	      }
103	    }
104	  }
105	
106	  let rebuildTimer: NodeJS.Timeout | undefined;
107	  function scheduleRebuild(): void {
108	    if (rebuildTimer) clearTimeout(rebuildTimer);
109	    rebuildTimer = setTimeout(() => {
110	      try {
111	        buildSite({ contentDir, outputDir, templatesDir });
112	        broadcastReload();
113	      } catch (err) {
114	        // eslint-disable-next-line no-console
115	        console.error('Rebuild failed:', err instanceof Error ? err.message : err);
116	      }
117	    }, REBUILD_DEBOUNCE_MS);
118	  }
119	
120	  const watchPaths = [contentDir, templatesDir].filter(
121	    (dir): dir is string => !!dir && fs.existsSync(dir)
122	  );
123	  const watcher: FSWatcher = watch(watchPaths, { ignoreInitial: true });
124	  watcher.on('add', scheduleRebuild);
125	  watcher.on('change', scheduleRebuild);
126	  watcher.on('unlink', scheduleRebuild);
127	
128	  await new Promise<void>((resolve) => watcher.once('ready', () => resolve()));
129	  await new Promise<void>((resolve) => server.listen(port, resolve));
130	
131	  const actualPort = (server.address() as AddressInfo).port;
132	
133	  return {
134	    port: actualPort,
135	    async close(): Promise<void> {
136	      if (rebuildTimer) clearTimeout(rebuildTimer);
137	      for (const client of wss.clients) {
138	        client.terminate();
139	      }
140	      await watcher.close();
141	      await new Promise<void>((resolve) => wss.close(() => resolve()));
142	      await new Promise<void>((resolve) => server.close(() => resolve()));
143	    },
144	  };
145	}
